import type { NavVisibilityInput } from './appNavigation';

export const getNavUnlockHints = (input: NavVisibilityInput): string[] => {
  const hints: string[] = [];

  if (!input.hasProfile) {
    return [
      'Complete your company profile (step 1) to unlock bill upload, footprint, and reporting.',
    ];
  }

  if (!input.hasAssessment) {
    hints.push(
      'Upload bills or use Data → Data connectors, then calculate your footprint — pick one report goal next.',
    );
  } else {
    hints.push(
      'Pick one report goal under Compliance → Disclosure reports. Operations and Data connectors stay in the sidebar.',
    );
  }

  if (input.hasProfile && input.hasAssessment && input.hasExportIntent !== true) {
    hints.push('Set export intent in Compliance Hub only if you sell outside India.');
  }

  return hints;
};
